(8, '0000', '76.01', '1.03.0.00.0.00.01.0000', '16  TAHUN 2020', '2020-01-03', 'pengangkatan penjaga kantor dinas pekerjaan umum dan penataan ruang kabupaten pasangkayu tahun 2020', '197508022006041011', 'kepala dinas', 'Pembina Tingkat I, IV/b', 'Budiyansa, ST', '{\"0\": {\"nip\": \"111111111111111111\", \"nama\": \"Zainal Abidin\", \"jabatan\": \"honorer\", \"pangkat\": \"Juru , I/-\", \"jabatan_sk\": \"Penjaga kantor\"}, \"1\": {\"nip\": \"111111111111111112\", \"nama\": \"Agung Reynaldi\", \"jabatan\": \"honorer\", \"pangkat\": \"Juru , I/-\", \"jabatan_sk\": \"Penjaga kantor\"}}', 0, '{\"0\": {\"isi\": \"bahwa untuk keamanan aset kantor pada Dinas Pekerjaan Umum dan Penataan Ruang Pemerintah Daerah Kabupaten Pasangkayu, maka dipandang perlu mengangkat Penjaga Kantor Dinas Pekerjaan Umum Kabupaten Pasangkayu Tahun 2020;\"}, \"1\": {\"isi\": \"bahwa yang tersebut namanya dalam lampiran keputusan ini dipandang cakap dan mampu melaksanakan tugas;\"}, \"2\": {\"isi\": \"bahwa pengangkatan sebagaimana dimaksud pada point a perlu ditetapkan dalam Keputusan Kepala Dinas.\"}}', '{\"0\": {\"isi\": \"Undang-Undang Nomor 28 Tahun 1999 tentang Penyelenggaraan Pemerintahan yang bersih dan bebas Korupsi, Kolusi dan Nepotisme (Lembaran Negara Republik Indonesia Tahun 1999 Nomor 75, Tambahan Lembaran Negara Republik Indonesia Nomor 3581);\"}, \"1\": {\"isi\": \"Undang-Undang Nomor 28 tahun 2000 tentang usaha dan peran masyarakat Jasa Konstruksi (Lembaran Negara Republik Indonesia tahun 2000 Nomor 63);\"}, \"2\": {\"isi\": \"Undang-Undang Nomor 7 Tahun 2003 tentang Pembentukan Kabupaten Luwu Timur dan Kabupaten Mamuju Utara di Provinsi Sulawesi Selatan (Lembaran Negara Tahun 2003 Nomor 27, Tambahan Lembaran NegaraNomor 4270);\"}, \"3\": {\"isi\": \"Undang-Undang Nomor 17 Tahun 2003 tentang Keuangan Negara (Lembaran Negara Republik Indonesia Tahun 2003 Nomor 47, Tambahan Lembaran Negara Republik Indonesia Nomor 4286);\"}, \"4\": {\"isi\": \"Undang-Undang Nomor 1 Tahun 2004 tentang Perbendaharaan Negara (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 5, Tambahan Lembaran Negara Republik Indonesia Nomor 4355);\"}, \"5\": {\"isi\": \"Undang-Undang Nomor 33 Tahun 2004 tentang Perimbangan Keuangan Antara Pemerintah Pusat dan Pemerintah Daerah (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 126, Tambahan Lembaran Negara Republik Indonesia Nomor 4438);\"}, \"6\": {\"isi\": \"Undang-Undang Nomor 2 Tahun 2017 tentang Jasa Konstruksi;\"}, \"7\": {\"isi\": \"Peraturan Presiden Republik Indonesia Nomor 16 Tahun 2019 tentang Pengadaan Barang/Jasa Pemerintah;\"}, \"8\": {\"isi\": \"Peraturan Pemerintah Nomor 61 Tahun 2017 tentang Perubahan Nama Kabupaten Mamuju Utara menjadi Kabupaten Pasangkayu di Provinsi Sulawesi Barat (Lembaran Negara Republik Indonesia Tahun 2017 Nomor 312, Tambahan Lembaran Negara Republik Indonesia Nomor 6715);\"}, \"9\": {\"isi\": \"Peraturan Menteri Dalam Negeri Nomor 13 Tahun 2006 tentang Pedoman Pengelolaan Keuangan Daerah sebagaimana telah diubah dengan Peraturan Menteri Dalam Negeri Nomor 59 Tahun 2007 tentang Perubahan Atas Peraturan Menteri Dalam Negeri Nomor 13 Tahun 2006 tentang Pedoman Pengelolaan Keuangan Daerah;\"}, \"10\": {\"isi\": \"Peraturan Menteri Dalam Negeri Nomor 33 Tahun 2019 tentang Pedoman Penyusunan Anggaran Pendapatan dan Belanja Daerah Tahun Anggaran 2020;\"}, \"11\": {\"isi\": \"Peraturan Daerah Kabupaten Mamuju Utara Nomor 5 Tahun 2006 tentang pokok-pokok Pengelolaan Keuangan Daerah (Lembaran Daerah Nomor 5 Tahun 2006, Tambahan Lembaran Daerah Nomor 5);\"}, \"12\": {\"isi\": \"Peraturan Daerah Kabupaten Pasangkayu Nomor 10 Tahun 2019 tanggal 30 Desember 2019 tentang Anggaran pendapatan dan Belanja Daerah Tahun Anggaran 2020;\"}, \"13\": {\"isi\": \"Peraturan Bupati Kabupaten Pasangkayu Nomor 47 Tahun 2018 tanggal 30 Desember 2019 tentang Penjabaran Anggaran Pendapatan dan Belanja Daerah Kebupaten Pasangkayu Tahun Anggaran 2020.\"}}', '{\"0\": {\"isi\": \"Tugas Pejabat sebagaimana dimaksud pada diktum Kesatu adalah :\", \"p_l\": \"P\"}, \"1\": {\"isi\": \"Melaksanakan Pengamanan secara menyeluruh di lokasi kerja, baik perkantoran dan lingkungan untuk memastikan kondisi keamanan kantor;\", \"p_l\": \"L\"}, \"2\": {\"isi\": \"Melakukan pemeriksaan pada tamu / pemilik yang akan masuk ke area kantor/kerja terutama malam hari ;\", \"p_l\": \"L\"}, \"3\": {\"isi\": \"Menyalakan dan Mematikan lampu Setelah Jaga malam;\", \"p_l\": \"L\"}, \"4\": {\"isi\": \"Mengecek Kunci-kunci pintu, jendela dan pagar kantor\", \"p_l\": \"L\"}, \"5\": {\"isi\": \"Membuat Laporan penting kejadian-kejadian penting selama masa penjagaan pada buku laporan\", \"p_l\": \"L\"}}', '{\"0\": {\"isi\": \"Segala biaya yang timbul akibat keputusan ini dibebankan kepada Pos Anggaran Dinas Pekerjaan Umum dan Penataan Ruang Kabupaten Pasangkayu Tahun Anggaran 2020.\", \"p_l\": \"P\"}}', '{\"0\": {\"isi\": \"Keputusan ini mulai berlaku pada tanggal ditetapkan dan apabila terdapat kekeliruan didalamnya akan diperbaharui sebagaimana mestinya.\", \"p_l\": \"P\"}}', '{}', '{\"0\": {\"tembusan\": \"Bupati                                            Pasangkayu, di Pasangkayu\"}, \"1\": {\"tembusan\": \"Sekretaris Daerah Kabupaten Pasangkayu di Pasangkayu\"}, \"2\": {\"tembusan\": \"Inspektur Inspektorat Kabupaten Pasangkayu di Pasangkayu\"}, \"3\": {\"tembusan\": \"Kepala Badan PKAD Kabupaten Pasangkayu di Pasangkayu\"}, \"4\": {\"tembusan\": \"Masing-masing yang bersangkutan\"}, \"5\": {\"tembusan\": \"Pertinggal\"}}', '', '', '0000-00-00 00:00:00', '', '0000-00-00 00:00:00', '', 0, 0),
(9, '0000', '76.01', '1.03.0.00.0.00.01.0000', '8  TAHUN 2020', '2020-01-03', 'Pembentukan Tim Koordinasi DAK Bidang Jalan dan Petugas Pelaporan e-Monitoring Dana Alokasi Khusus Bidang Jalan', '197508022006041011', 'kepala dinas', 'Pembina Tingkat I, IV/b', 'Budiyansa, ST', '{\"0\": {\"nip\": \"197508022006041011\", \"nama\": \"Budiyansa, ST\", \"jabatan\": \"kepala dinas\", \"pangkat\": \"Pembina Tingkat I, IV/b\", \"jabatan_sk\": \"Pembina\"}, \"1\": {\"nip\": \"197501192007011013\", \"nama\": \"Muammar Nur, ST\", \"jabatan\": \"kabid bina marga\", \"pangkat\": \"Penata Tingkat I, III/d\", \"jabatan_sk\": \"Ketua\"}, \"2\": {\"nip\": \"198301012010011020\", \"nama\": \"I Nyoman Sumerta, ST\", \"jabatan\": \"kasie pembangunan jalan\", \"pangkat\": \"Penata , III/c\", \"jabatan_sk\": \"Sekretaris\"}, \"3\": {\"nip\": \"197712242012122001\", \"nama\": \"Lelianti\", \"jabatan\": \"STAFF\", \"pangkat\": \"Pengatur Muda Tingkat I, II/b\", \"jabatan_sk\": \"Bendahara\"}, \"4\": {\"nip\": \"197110122009031001\", \"nama\": \"Patahuddin, ST\", \"jabatan\": \"kasie pemeliharaan jalan,jembatan dan peralatan\", \"pangkat\": \"Penata Tingkat I, III/d\", \"jabatan_sk\": \"Koordinator/Anggota Tim Koordinasi\"}, \"5\": {\"nip\": \"197910012011011004\", \"nama\": \"Nardin, ST\", \"jabatan\": \"kasie pembangunan jembatan\", \"pangkat\": \"Penata , III/c\", \"jabatan_sk\": \"Koordinator/Anggota Tim Koordinasi\"}, \"6\": {\"nip\": \"198407252009031001\", \"nama\": \"Felix Datuan, ST\", \"jabatan\": \"kasubag keuangan\", \"pangkat\": \"Penata , III/c\", \"jabatan_sk\": \"Anggota Tim Koordinasi\"}, \"7\": {\"nip\": \"197701272008042001\", \"nama\": \"Evi Yanti, ST\", \"jabatan\": \"STAFF\", \"pangkat\": \"Penata Tingkat I, III/d\", \"jabatan_sk\": \"Anggota Tim Koordinasi\"}, \"8\": {\"nip\": \"197510032014102002\", \"nama\": \"Yulita Veryanti Siahaan, SE\", \"jabatan\": \"STAFF\", \"pangkat\": \"Penata Muda Tingkat I, III/b\", \"jabatan_sk\": \"Anggota Tim Koordinasi\"}, \"9\": {\"nip\": \"197804012006041024\", \"nama\": \"Tahmil, SH\", \"jabatan\": \"STAFF\", \"pangkat\": \"Penata Muda, III/a\", \"jabatan_sk\": \"Anggota Tim Koordinasi\"}, \"10\": {\"nip\": \"197009302012121003\", \"nama\": \"Kamaruddin, SE\", \"jabatan\": \"STAFF\", \"pangkat\": \"Penata Muda Tingkat I, III/b\", \"jabatan_sk\": \"Anggota Tim Koordinasi\"}, \"11\": {\"nip\": \"198610102012121001\", \"nama\": \"Abd. Rifai, SH\", \"jabatan\": \"STAFF\", \"pangkat\": \"Penata Muda, III/a\", \"jabatan_sk\": \"Anggota Tim Koordinasi\"}, \"12\": {\"nip\": \"198406072019032008\", \"nama\": \"Mawaddah, ST\", \"jabatan\": \"STAFF\", \"pangkat\": \"Penata Muda, III/a\", \"jabatan_sk\": \"Anggota Tim Koordinasi\"}, \"13\": {\"nip\": \"197201221995041001\", \"nama\": \"Syamsuddin Sangkala\", \"jabatan\": \"STAFF\", \"pangkat\": \"Pengatur , II/c\", \"jabatan_sk\": \"Anggota Tim Koordinasi\"}, \"14\": {\"nip\": \"196804122007011074\", \"nama\": \"I Made Tamayasa\", \"jabatan\": \"STAFF\", \"pangkat\": \"Pengatur Tingkat I, II/d\", \"jabatan_sk\": \"Anggota Tim Koordinasi\"}, \"15\": {\"nip\": \"197807012010011002\", \"nama\": \"Asham\", \"jabatan\": \"STAFF\", \"pangkat\": \"Pengatur , II/c\", \"jabatan_sk\": \"Anggota Tim Koordinasi\"}, \"16\": {\"nip\": \"198303262012121004\", \"nama\": \"Muhammad Mustaqim Nur\", \"jabatan\": \"STAFF\", \"pangkat\": \"Pengatur Muda Tingkat I, II/b\", \"jabatan_sk\": \"Anggota Tim Koordinasi\"}, \"17\": {\"nip\": \"197804022014051001\", \"nama\": \"Asnawir\", \"jabatan\": \"STAFF\", \"pangkat\": \"Pengatur Muda Tingkat I, II/b\", \"jabatan_sk\": \"Anggota Tim Koordinasi\"}, \"18\": {\"nip\": \"198410172014051001\", \"nama\": \"Syamsuri Rustam\", \"jabatan\": \"STAFF\", \"pangkat\": \"Pengatur Muda Tingkat I, II/b\", \"jabatan_sk\": \"Anggota Tim Koordinasi\"}, \"19\": {\"nip\": \"196807112014101001\", \"nama\": \"Muharram\", \"jabatan\": \"STAFF\", \"pangkat\": \"Pengatur Muda Tingkat I, II/b\", \"jabatan_sk\": \"Anggota Tim Koordinasi\"}, \"20\": {\"nip\": \"197706132014091002\", \"nama\": \"Boby S. Pakaya\", \"jabatan\": \"STAFF\", \"pangkat\": \"Pengatur Muda, II/a\", \"jabatan_sk\": \"Anggota Tim Koordinasi\"}, \"21\": {\"nip\": \"198502112015031004\", \"nama\": \"Dirgantara, ST\", \"jabatan\": \"STAFF\", \"pangkat\": \"Penata Muda Tingkat I, III/b\", \"jabatan_sk\": \"Anggota Tim Koordinasi\"}, \"22\": {\"nip\": \"197601032006042007\", \"nama\": \"Irmawati, SE\", \"jabatan\": \"kasubag umum dan kepegawaian\", \"pangkat\": \"Penata , III/c\", \"jabatan_sk\": \"Anggota Tim Koordinasi\"}, \"23\": {\"nip\": \"198509192010012002\", \"nama\": \"Santi, SE\", \"jabatan\": \"STAFF\", \"pangkat\": \"Penata Muda Tingkat I, III/b\", \"jabatan_sk\": \"Anggota Tim Koordinasi\"}, \"24\": {\"nip\": \"198308082012121002\", \"nama\": \"Fuady Kahar, SH\", \"jabatan\": \"STAFF\", \"pangkat\": \"Penata Muda Tingkat I, III/b\", \"jabatan_sk\": \"Anggota Tim Koordinasi\"}, \"25\": {\"nip\": \"197709302012122002\", \"nama\": \"Rachmiy. S\", \"jabatan\": \"STAFF\", \"pangkat\": \"Pengatur Muda Tingkat I, II/b\", \"jabatan_sk\": \"Anggota Tim Koordinasi\"}, \"26\": {\"nip\": \"198007112006041010\", \"nama\": \"Alwi Mansyur, A.Md\", \"jabatan\": \"Plt. kasubag program\", \"pangkat\": \"Penata Muda, III/a\", \"jabatan_sk\": \"Petugas e-Monitoring\"}, \"27\": {\"nip\": \"198504172019032010\", \"nama\": \"Vilma Erhid Salla, ST\", \"jabatan\": \"STAFF\", \"pangkat\": \"Penata Muda, III/a\", \"jabatan_sk\": \"Petugas e-Monitoring\"}, \"28\": {\"nip\": \"198510092014091002\", \"nama\": \"Agussalim T\", \"jabatan\": \"STAFF\", \"pangkat\": \"Pengatur Muda, II/a\", \"jabatan_sk\": \"Anggota Tim Koordinasi\"}}', 0, '{\"0\": {\"isi\": \"bahwa untuk Peningkatan akuntabilitas dan pelaporan DAK pada sektor infrastruktur khususnya Bidang Jalan serta Peningkatan kemampuan Pemda untuk menghasilkan output dan laporan DAK yang dipersyaratkan dan meningkatkan pengendalian internal Pemerintah Daerah Kabupaten Pasangkayu, maka dipandang perlu mengangkat Tim Koordinasi dan Petugas Pelaporan Monitoring Dana Alokasi Khusus Bidang Infrastruktur;\"}, \"1\": {\"isi\": \"bahwa yang tersebut namanya dalam lampiran keputusan ini dipandang cakap dan mampu melaksanakan tugas;\"}, \"2\": {\"isi\": \"bahwa sebagaimana dimaksud pada point a perlu ditetapkan dalam keputusan Kepala Dinas Pekerjaan Umum dan Penataan Ruang.\"}}', '{\"0\": {\"isi\": \"Undang-Undang Nomor 28 Tahun 1999 tentang penyelenggaraan Negara yang bersih dan bebas dari korupsi dan nepotisme (Lembaran Negara Republik Indonesia Tahun 1999 Nomor 75, Tambahan Lembaran Negara Nomor 3851);\"}, \"1\": {\"isi\": \"Undang-Undang Nomor 7 Tahun 2003 tentang Pembentukan Kabupaten Luwu Timur dan Kabupaten Mamuju Utara di Provinsi Sulawesi Selatan (Lembaran Negara Republik Indonesia Tahun 2003 Nomor 27, Tambahan Lembaran Negara Nomor 4270);\"}, \"2\": {\"isi\": \"Undang-Undang Nomor 17 Tahun 2003 tentang Keuangan Negara (Lembaran Negara Republik Indonesia Tahun 2003 Nomor 47, Tambahan Lembaran Negara Nomor 4286);\"}, \"3\": {\"isi\": \"Undang-Undang Nomor 1 Tahun 2004 tentang Perbendaharaan Negara (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 5, Tambahan Lembaran Negara Nomor 4355);\"}, \"4\": {\"isi\": \"Undang-Undang Nomor 32 Tahun 2004 tentang Pemerintah Daerah (Lembaran Negara Republik Indonesia Tahun 2004 Nomor125, Tambahan Lembaran Negara Nomor 4437) sebagimana telah diubah beberapa kali terakhir dengan Undang-undang Nomor 12 Tahun 2008 tentang Perubahan kedua atas undang-undang Nomor 32 Tahun 2004 tentang Pemerintahan Daerah (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 59, Tambahan Lembaran Negara Nomor 4844);\"}, \"5\": {\"isi\": \"Peraturan Pemerintah Nomor 58 Tahun 2005 tentang Pengelolaan Keuangan Daerah (Lembaran Negara Republik Indonesia Tahun 2005 Nomor 140, Tambahan Lembaran Negara Republik Indonesia Nomor 4578);\"}, \"6\": {\"isi\": \"Undang-Undang Nomor 33 Tahun 2004 tentang Perimbangan Keuangan Antara Pemerintah Pusat dan Pemerintah Daerah (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 126, Tambahan Lembaran Negara Republik Indonesia Nomor 4438)\"}, \"7\": {\"isi\": \"Peraturan Menteri Pekerjaan Umum dan Perumahan Rakyat Nomor 21/PRT/M/2017 Tahun 2017 tentang Petunjuk Operasional Penyelenggaraan Dana Alokasi Khusus Infrastruktur Pekerjaan Umum dan Perumahan Rakyat;\"}, \"8\": {\"isi\": \"Peraturan Menteri Dalam Negeri Nomor 13 Tahun 2006 tentang Pedoman Pengelolaan Keuangan Daerah sebagaimana telah diubah dengan Peraturan Menteri Dalam Negeri Nomor 59 Tahun 2007 tentang Perubahan Atas Peraturan Menteri Dalam Negeri Nomor 13 Tahun 2006 tentang Pedoman Pengelolaan Keuangan Daerah;\"}, \"9\": {\"isi\": \"Peraturan Daerah Kabupaten Pasangkayu Nomor 35 Tahun 2016 tentang Pembentukan Organisasi Perangkat Daerah;\"}, \"10\": {\"isi\": \"Peraturan Daerah Kabupaten Pasangkayu Nomor 10 Tahun 2019 tanggal 30 Desember 2019 tentang Anggaran pendapatan dan Belanja Daerah Tahun Anggaran 2020;\"}, \"11\": {\"isi\": \"Peraturan Bupati Kabupaten Pasangkayu Nomor 47 Tahun 2018 tanggal 30 Desember 2019 tentang Penjabaran Anggaran Pendapatan dan Belanja Daerah Kebupaten Pasangkayu Tahun Anggaran 2020.\"}}', '{\"0\": {\"isi\": \"Tim Koordinasi sebagaimana dimaksud pada Diktum Kesatu mempunyai Fungsi dan Tugas sebagai berikut :\", \"p_l\": \"P\"}, \"1\": {\"isi\": \"Melakukan Review dan Verifikasi usulan proposal DAK Bidang Infrastruktur Kabupaten, selanjutnya usulan proposal DAK kabupeten ditandatangani oleh Bupati\", \"p_l\": \"L\"}, \"2\": {\"isi\": \"Melakukan verifikasi Data teknis Dak bidang infrastruktur secara berkala\", \"p_l\": \"L\"}, \"3\": {\"isi\": \"Melakukan fasilitasi penyusunan harga satuan Kabupaten\", \"p_l\": \"L\"}, \"4\": {\"isi\": \"Melaksanakan pemantauannya terhadap pelaksanaan dak bidang infrastruktur oleh pemerintah Kabupaten\", \"p_l\": \"L\"}, \"5\": {\"isi\": \"Kegiatan pemantauan termasuk diantaranya Inventarisasi permasalahan terkait pencapaian progres fisik dan keuangan dak bidang infrastruktur di daerah\", \"p_l\": \"L\"}, \"6\": {\"isi\": \"Melaksanakan evaluasi terhadap pelaksanaan dak bidang infrastruktur Oleh pemerintah Kabupaten\", \"p_l\": \"L\"}, \"7\": {\"isi\": \"Memberikan saran, Masukan, maupun rekomendasi kepada Bupati terkait penyelenggaraan dan ke depan di Kabupaten\", \"p_l\": \"L\"}, \"8\": {\"isi\": \"Menyiapkan laporan triwulanan dan tahunan terkait penyelenggaraan dak bidang infrastruktur di Kabupaten,Terkait Dan menyampaikan Kepada Tim koordinasi kementerian DAK bidang Infrastruktur Sebagaimana mekanisme pelaporan dalam peraturan menteri Pekerjaan umum dan perumahan rakyat\", \"p_l\": \"L\"}}', '{\"0\": {\"isi\": \"Petugas Pelaporan sebagaimana dimaksud pada Diktum Kesatu mempunyai Fungsi dan Tugas sebagai berikut :\", \"p_l\": \"P\"}, \"1\": {\"isi\": \"Melakukan pelaporan DAK Bidang Infrastruktur Bidang Binamarga;\", \"p_l\": \"L\"}, \"2\": {\"isi\": \"Melakukan verifikasi pelaporan DAK Bidang Infrastruktur.\", \"p_l\": \"L\"}}', '{\"0\": {\"isi\": \"Segala biaya yang timbul akibat keputusan ini dibebankan kepada APBD Dinas Pekerjaan Umum dan Penataan Ruang Kabupaten Pasangkayu Tahun Anggaran 2020.\", \"p_l\": \"P\"}}', '{\"0\": {\"isi\": \"Keputusan ini mulai berlaku pada tanggal ditetapkan dan apabila terdapat kekeliruan didalamnya akan diperbaharui sebagaimana mestinya.\", \"p_l\": \"P\"}}', '{\"0\": {\"tembusan\": \"Bupati                                            Pasangkayu, di Pasangkayu;\"}, \"1\": {\"tembusan\": \"Sekretaris Daerah Kabupaten Pasangkayu di Pasangkayu;\"}, \"2\": {\"tembusan\": \"Inspektur Inspektorat Kabupaten Pasangkayu di Pasangkayu;\"}, \"3\": {\"tembusan\": \"Kepala Badan PKAD Kabupaten Pasangkayu di Pasangkayu;\"}, \"4\": {\"tembusan\": \"Masing-masing yang bersangkutan;\"}, \"5\": {\"tembusan\": \"Pertinggal.\"}}', '', '', '0000-00-00 00:00:00', '', '0000-00-00 00:00:00', '', 0, 0),
(10, '0000', '76.01', '1.03.0.00.0.00.01.0000', '15  TAHUN 2020', '2020-01-03', 'pengangkatan Pengantar/administrasi surat-menyurat dinas pekerjaan umum dan penataan ruang kabupaten pasangkayu tahun 2020', '197508022006041011', 'kepala dinas', 'Pembina Tingkat I, IV/b', 'Budiyansa, ST', '{\"0\": {\"nip\": \"111111111111111115\", \"nama\": \"Nurafni Rusdin, SE\", \"jabatan\": \"honorer\", \"pangkat\": \"Juru , I/-\", \"jabatan_sk\": \"Pengantar/Administrasi Surat-Menyurat\"}, \"1\": {\"nip\": \"111111111111111113\", \"nama\": \"Sudirman\", \"jabatan\": \"honorer\", \"pangkat\": \"Juru , I/-\", \"jabatan_sk\": \"Pengantar/Administrasi Surat-Menyurat\"}}', 0, '{\"0\": {\"isi\": \"bahwa untuk kelancaran pelaksanaan administrasi dokumen persuratan yang baik pada Dinas Pekerjaan Umum dan Penataan Ruang Pemerintah Daerah Kabupaten Pasangkayu, maka dipandang perlu mengangkat Pengantar Surat pada Dinas Pekerjaan Umum Kabupaten Pasangkayu;\"}, \"1\": {\"isi\": \"bahwa yang tersebut namanya dalam lampiran keputusan ini dipandang cakap dan mampu melaksanakan tugas;\"}, \"2\": {\"isi\": \"bahwa pengangkatan sebagaimana dimaksud pada point a perlu ditetapkan dalam Keputusan Kepala Dinas.\"}}', '{\"0\": {\"isi\": \"Undang-Undang Nomor 28 Tahun 1999 tentang Penyelenggaraan Pemerintahan yang bersih dan bebas Korupsi, Kolusi dan Nepotisme (Lembaran Negara Republik Indonesia Tahun 1999 Nomor 75, Tambahan Lembaran Negara Republik Indonesia Nomor 3581);\"}, \"1\": {\"isi\": \"Undang-Undang Nomor 28 tahun 2000 tentang usaha dan peran masyarakat Jasa Konstruksi (Lembaran Negara Republik Indonesia tahun 2000 Nomor 63);\"}, \"2\": {\"isi\": \"Undang-Undang Nomor 7 Tahun 2003 tentang Pembentukan Kabupaten Luwu Timur dan Kabupaten Mamuju Utara di Provinsi Sulawesi Selatan (Lembaran Negara Tahun 2003 Nomor 27, Tambahan Lembaran NegaraNomor 4270);\"}, \"3\": {\"isi\": \"Undang-Undang Nomor 17 Tahun 2003 tentang Keuangan Negara (Lembaran Negara Republik Indonesia Tahun 2003 Nomor 47, Tambahan Lembaran Negara Republik Indonesia Nomor 4286);\"}, \"4\": {\"isi\": \"Undang-Undang Nomor 1 Tahun 2004 tentang Perbendaharaan Negara (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 5, Tambahan Lembaran Negara Republik Indonesia Nomor 4355);\"}, \"5\": {\"isi\": \"Undang-Undang Nomor 33 Tahun 2004 tentang Perimbangan Keuangan Antara Pemerintah Pusat dan Pemerintah Daerah (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 126, Tambahan Lembaran Negara Republik Indonesia Nomor 4438);\"}, \"6\": {\"isi\": \"Undang-Undang Nomor 2 Tahun 2017 tentang Jasa Konstruksi;\"}, \"7\": {\"isi\": \"Peraturan Presiden Republik Indonesia Nomor 16 Tahun 2019 tentang Pengadaan Barang/Jasa Pemerintah;\"}, \"8\": {\"isi\": \"Peraturan Pemerintah Nomor 61 Tahun 2017 tentang Perubahan Nama Kabupaten Mamuju Utara menjadi Kabupaten Pasangkayu di Provinsi Sulawesi Barat (Lembaran Negara Republik Indonesia Tahun 2017 Nomor 312, Tambahan Lembaran Negara Republik Indonesia Nomor 6715);\"}, \"9\": {\"isi\": \"Peraturan Menteri Dalam Negeri Nomor 13 Tahun 2006 tentang Pedoman Pengelolaan Keuangan Daerah sebagaimana telah diubah dengan Peraturan Menteri Dalam Negeri Nomor 59 Tahun 2007 tentang Perubahan Atas Peraturan Menteri Dalam Negeri Nomor 13 Tahun 2006 tentang Pedoman Pengelolaan Keuangan Daerah;\"}, \"10\": {\"isi\": \"Peraturan Menteri Dalam Negeri Nomor 33 Tahun 2019 tentang Pedoman Penyusunan Anggaran Pendapatan dan Belanja Daerah Tahun Anggaran 2020;\"}, \"11\": {\"isi\": \"Peraturan Daerah Kabupaten Mamuju Utara Nomor 5 Tahun 2006 tentang pokok-pokok Pengelolaan Keuangan Daerah (Lembaran Daerah Nomor 5 Tahun 2006, Tambahan Lembaran Daerah Nomor 5);\"}, \"12\": {\"isi\": \"Peraturan Daerah Kabupaten Pasangkayu Nomor 10 Tahun 2019 tanggal 30 Desember 2019 tentang Anggaran pendapatan dan Belanja Daerah Tahun Anggaran 2020;\"}, \"13\": {\"isi\": \"Peraturan Bupati Kabupaten Pasangkayu Nomor 47 Tahun 2018 tanggal 30 Desember 2019 tentang Penjabaran Anggaran Pendapatan dan Belanja Daerah Kebupaten Pasangkayu Tahun Anggaran 2020.\"}}', '{\"0\": {\"isi\": \"Tugas Personil sebagaimana dimaksud pada diktum Kesatu adalah sebagai berikut :\", \"p_l\": \"P\"}, \"1\": {\"isi\": \"Menerima dan mempelajari surat;\", \"p_l\": \"L\"}, \"2\": {\"isi\": \"Menyortir surat menurut jenis dan sifatnya;\", \"p_l\": \"L\"}, \"3\": {\"isi\": \"Mencatat dan mengendalikan surat;\", \"p_l\": \"L\"}, \"4\": {\"isi\": \"Mengantar dan memberi lembar pengantar surat/ekspedisi;\", \"p_l\": \"L\"}, \"5\": {\"isi\": \"Mendokumentasikan surat;\", \"p_l\": \"L\"}, \"6\": {\"isi\": \"Melaporkan hasil pelaksanaan tugas secara tertulis dan lisan kepada atasan sesuai prosedur yang berlaku;\", \"p_l\": \"L\"}, \"7\": {\"isi\": \"Melaksanakan tugas kedinasan lain yang diperintahkan pimpinan baik tertulia maupun lisan.\", \"p_l\": \"L\"}}', '{\"0\": {\"isi\": \"Segala biaya yang timbul akibat keputusan ini dibebankan kepada Pos Anggaran Dinas Pekerjaan Umum dan Penataan Ruang Kabupaten Pasangkayu Tahun Anggaran 2020.\", \"p_l\": \"P\"}}', '{\"0\": {\"isi\": \"Keputusan ini mulai berlaku pada tanggal ditetapkan dan apabila terdapat kekeliruan didalamnya akan diperbaharui sebagaimana mestinya.\", \"p_l\": \"P\"}}', '{}', '{\"0\": {\"tembusan\": \"Bupati                                            Pasangkayu, di Pasangkayu\"}, \"1\": {\"tembusan\": \"Sekretaris Daerah Kabupaten Pasangkayu di Pasangkayu\"}, \"2\": {\"tembusan\": \"Inspektur Inspektorat Kabupaten Pasangkayu di Pasangkayu\"}, \"3\": {\"tembusan\": \"Kepala Badan PKAD Kabupaten Pasangkayu di Pasangkayu\"}, \"4\": {\"tembusan\": \"Masing-masing yang bersangkutan\"}, \"5\": {\"tembusan\": \"Pertinggal\"}}', '', '', '0000-00-00 00:00:00', '', '0000-00-00 00:00:00', '', 0, 0),
