(68, '2023', '76.01', '1.03.0.00.0.00.01.0000', '03 TAHUN 2023', '2023-01-11', 'pengangkatan pejabat penatausahaan keuangan  dinas pekerjaan umum dan penataan ruang kabupaten pasangkayu tahun 2023', '198006152006041018', 'kepala', 'Pembina Tingkat I, IV/b', 'Sumarlin, ST, M.AP', '{\"0\":{\"nama\":\"Felix Datuan, ST\",\"pangkat\":\"Penata Tingkat I, III/d\",\"nip\":\"198407252009031001\",\"jabatan\":\"Kepala Sub Bagian Keuangan\",\"jabatan_sk\":\"Pejabat Penatausahaan Keuangan\"}}', 0, '{\"0\":{\"isi\":\"bahwa untuk menyediakan pengelolaan keuangan Dinas Pekerjaan Umum dan Penataan Ruang Kabupaten Pasangkayu, maka dipandang perlu mengangkat Pejabat Penatausahaan Keuangan pada Dinas Pekerjaan Umum dan Penataan Ruang Kabupaten Pasangkayu;\"},\"1\":{\"isi\":\"bahwa yang tersebut namanya dalam lampiran keputusan ini dipandang cakap dan mampu melaksanakan tugas;\"},\"2\":{\"isi\":\"bahwa sebagaimana dimaksud pada point a perlu ditetapkan dalam keputusan Kepala Dinas Pekerjaan Umum dan Penataan Ruang.\"}}', '{\"0\":{\"isi\":\"Undang-Undang Nomor 28 Tahun 1999 tentang penyelenggaraan Negara yang bersih dan bebas dari korupsi dan nepotisme (Lembaran Negara Republik Indonesia Tahun 1999 Nomor 75, Tambahan Lembaran Negara Nomor 3851);\"},\"1\":{\"isi\":\"Undang-Undang Nomor 7 Tahun 2003 tentang Pembentukan Kabupaten Luwu Timur dan Kabupaten Mamuju Utara di Provinsi Sulawesi Selatan (Lembaran Negara Republik Indonesia Tahun 2003 Nomor 27, Tambahan Lembaran Negara Nomor 4270);\"},\"2\":{\"isi\":\"Undang-Undang Nomor 17 Tahun 2003 tentang Keuangan Negara (Lembaran Negara Republik Indonesia Tahun 2003 Nomor 47, Tambahan Lembaran Negara Nomor 4286);\"},\"3\":{\"isi\":\"Undang-Undang Nomor 1 Tahun 2004 tentang Perbendaharaan Negara (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 5, Tambahan Lembaran Negara Nomor 4355);\"},\"4\":{\"isi\":\"Undang-Undang Nomor 32 Tahun 2004 tentang Pemerintah Daerah (Lembaran Negara Republik Indonesia Tahun 2004 Nomor125, Tambahan Lembaran Negara Nomor 4437) sebagimana telah diubah beberapa kali terakhir dengan Undang-undang Nomor 12 Tahun 2008 tentang Perubahan kedua atas undang-undang Nomor 32 Tahun 2004 tentang Pemerintahan Daerah (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 59, Tambahan Lembaran Negara Nomor 4844);\"},\"5\":{\"isi\":\"Peraturan Pemerintah Nomor 58 Tahun 2005 tentang Pengelolaan Keuangan Daerah (Lembaran Negara Republik Indonesia Tahun 2005 Nomor 140, Tambahan Lembaran Negara Republik Indonesia Nomor 4578);\"},\"6\":{\"isi\":\"Undang-Undang Nomor 33 Tahun 2004 tentang Perimbangan Keuangan Antara Pemerintah Pusat dan Pemerintah Daerah (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 126, Tambahan Lembaran Negara Republik Indonesia Nomor 4438)\"},\"7\":{\"isi\":\"Peraturan Pemerintah Nomor 8 Tahun 2006 tentang Laporan Keuangan dan Kinerja Instansi Pemerintah (Lembaran Negara Republik Indonesia Tahun 2006 Nomor 25, Tambahan Lembaran Negara Republik Indonesia Nomor 4614);\"},\"8\":{\"isi\":\"Peraturan Menteri Dalam Negeri Nomor 77 Tahun 2020 tentang Pedoman Teknis Pengelolaan Keuangan Daerah;\"},\"9\":{\"isi\":\"Peraturan Daerah Kabupaten Pasangkayu Nomor 35 Tahun 2016 tentang Pembentukan Organisasi Perangkat Daerah;\"},\"10\":{\"isi\":\"Peraturan Daerah Kabupaten Pasangkayu Nomor 5 Tahun 2022 tanggal 30 Desember 2022 tentang Anggaran pendapatan dan Belanja Daerah Tahun Anggaran 2023;\"},\"11\":{\"isi\":\"Peraturan Bupati Kabupaten Pasangkayu Nomor 33 Tahun 2022 tanggal 30 Desember 2022 tentang Penjabaran Anggaran Pendapatan dan Belanja Daerah Kebupaten Pasangkayu Tahun Anggaran 2023.\"}}', '{\"0\":{\"isi\":\"PPK SKPD mempunyai tugas dan wewenang:\",\"p_l\":\"P\"},\"1\":{\"isi\":\"melakukan verifikasi SPP-UP, SPP-GU, SPP-TU, dan SPP-LS beserta bukti kelengkapannya yang diajukan oleh Bendahara Pengeluaran;\",\"p_l\":\"L\"},\"2\":{\"isi\":\"menyiapkan SPM;\",\"p_l\":\"L\"},\"3\":{\"isi\":\"melakukan verifikasi laporan pertanggungjawaban Bendahara Penerimaan dan Bendahara Pengeluaran;\",\"p_l\":\"L\"},\"4\":{\"isi\":\"melaksanakan fungsi akuntansi pada SKPD; dan\",\"p_l\":\"L\"},\"5\":{\"isi\":\"menyusun laporan keuangan SKPD.\",\"p_l\":\"L\"},\"6\":{\"isi\":\"Verifikasi oleh PPK SKPD dilakukan dengan tujuan untuk meneliti kelengkapan dan keabsahan.\",\"p_l\":\"P\"}}', '{\"0\":{\"isi\":\"Selain melaksanakan tugas dan wewenang pada angka 5, PPK SKPD melaksanakan tugas dan wewenang lainnya yaitu:\",\"p_l\":\"P\"},\"1\":{\"isi\":\"melakukan verifikasi SPP-UP, SPP-GU, SPP-TU, dan SPP-LS beserta bukti kelengkapannya yang diajukan oleh Bendahara lainnya;\",\"p_l\":\"L\"},\"2\":{\"isi\":\"melakukan verifikasi surat permintaan pembayaran atas pengembalian kelebihan pendapatan daerah dari bendahara penerimaan; dan\",\"p_l\":\"L\"},\"3\":{\"isi\":\"menerbitkan surat pernyataan verifikasi kelengkapan dan keabsahan SPP-UP, SPP-GU, SPP-TU dan SPP-LS beserta bukti kelengkapannya sebagai dasar penyiapan SPM.\",\"p_l\":\"L\"}}', '{\"0\":{\"isi\":\"Segala biaya yang timbul akibat keputusan ini dibebankan kepada APBD Dinas Pekerjaan Umum dan Penataan Ruang Kabupaten Pasangkayu Tahun Anggaran 2023.\",\"p_l\":\"P\"}}', '{\"0\":{\"isi\":\"Keputusan ini mulai berlaku pada tanggal ditetapkan dan apabila terdapat kekeliruan didalamnya akan diperbaharui sebagaimana mestinya.\",\"p_l\":\"P\"}}', '{\"0\":{\"tembusan\":\"Bupati                                            Pasangkayu, di Pasangkayu;\"},\"1\":{\"tembusan\":\"Sekretaris Daerah Kabupaten Pasangkayu di Pasangkayu;\"},\"2\":{\"tembusan\":\"Inspektur Inspektorat Kabupaten Pasangkayu di Pasangkayu;\"},\"3\":{\"tembusan\":\"Kepala Badan PKAD Kabupaten Pasangkayu di Pasangkayu;\"},\"4\":{\"tembusan\":\"Masing-masing yang bersangkutan;\"},\"5\":{\"tembusan\":\"Pertinggal.\"}}', '', '', '0000-00-00 00:00:00', '', '0000-00-00 00:00:00', '', 0, 0),
(69, '2023', '76.01', '1.03.0.00.0.00.01.0000', '04 TAHUN 2023', '2023-01-11', 'pengangkatan pejabat pelaksana teknis kegiatan (PPTK) dan tim teknis dinas pekerjaan umum dan penataan ruang kabupaten pasangkayu tahun 2022', '198006152006041018', 'kepala', 'Pembina Tingkat I, IV/b', 'Sumarlin, ST, M.AP', '{\"0\":{\"nama\":\"Nurmadina, S.Sos.M.Si\",\"pangkat\":\"Penata Tingkat I , III/d\",\"nip\":\"198208022003122003\",\"jabatan\":\"Pembina jasa konstruksi\",\"jabatan_sk\":\"PPTK/Tim Pembinaan Jasa Konstruksi\"},\"1\":{\"nama\":\"Muh. Hirman Madjid, ST\",\"pangkat\":\"Penata , III/c\",\"nip\":\"197511282011011002\",\"jabatan\":\"Tehnik tata bangunan dan perumahan\",\"jabatan_sk\":\"PPTK/Tim Teknis Bangunan Gedung dan Lingkungan\"},\"2\":{\"nama\":\"Rahmania, ST\",\"pangkat\":\"Penata , III/c\",\"nip\":\"198406172009032002\",\"jabatan\":\"Tehnik penyehatan lingkungan\",\"jabatan_sk\":\"PPTK/Tim Teknis Sanitasi dan Penyehatan Lingkungan\"},\"3\":{\"nama\":\"I Ketut Suriyana, ST\",\"pangkat\":\"Penata , III/c\",\"nip\":\"198404262011011011\",\"jabatan\":\"Tehnik penyehatan lingkungan\",\"jabatan_sk\":\"PPTK/Tim Teknis Air Minum\"},\"4\":{\"nama\":\"Patahuddin, ST. M.AP\",\"pangkat\":\"Penata Tingkat I, III/d\",\"nip\":\"197110122009031001\",\"jabatan\":\"Tehnik jalan dan jembatan\",\"jabatan_sk\":\"PPTK/Tim Teknis Pembangunan Jalan, Pemeliharaan Jalan dan Peralatan\"},\"5\":{\"nama\":\"Suriyana, ST\",\"pangkat\":\"Penata Muda Tingkat I, III/b\",\"nip\":\"198001282012122003\",\"jabatan\":\"Tehnik tata bangunan dan perumahan\",\"jabatan_sk\":\"PPTK/Tim Teknis Bidang Penataan Ruang\"},\"6\":{\"nama\":\"Evi Yanti, ST\",\"pangkat\":\"Penata Tingkat I, III/d\",\"nip\":\"197701272008042001\",\"jabatan\":\"Fungsional\",\"jabatan_sk\":\"PPTK/Tim Teknis Pembangunan Jembatan, Pemeliharaan Jembatan, Penggantian Jembatan\"},\"7\":{\"nama\":\"Irmawati, SE\",\"pangkat\":\"Penata , III/c\",\"nip\":\"197601032006042007\",\"jabatan\":\"kasubag umum dan kepegawaian\",\"jabatan_sk\":\"PPTK Sekretariat\"}}', 0, '{\"0\":{\"isi\":\"bahwa untuk pelaksanaan proses kerja Pengadaan Barang / Jasa Pemerintah yang efektif, efisien dan akuntabel pada Dinas Pekerjaan Umum dan Penataan Ruang Pemerintah Daerah Kabupaten Pasangkayu, maka dipandang perlu mengangkat Pejabat Pelaksana Teknis Kegiatan (PPTK) dan tim teknis pada Dinas Pekerjaan Umum Kabupaten Pasangkayu Tahun 2023;\"},\"1\":{\"isi\":\"bahwa yang tersebut namanya dalam lampiran keputusan ini dipandang cakap dan mampu melaksanakan tugas;\"},\"2\":{\"isi\":\"bahwa pengangkatan sebagaimana dimaksud pada point a perlu ditetapkan dalam Keputusan Kepala Dinas.\"}}', '{\"0\":{\"isi\":\"Undang-Undang Nomor 28 Tahun 1999 tentang Penyelenggaraan Pemerintahan yang bersih dan bebas Korupsi, Kolusi dan Nepotisme (Lembaran Negara Republik Indonesia Tahun 1999 Nomor 75, Tambahan Lembaran Negara Republik Indonesia Nomor 3581);\"},\"1\":{\"isi\":\"Undang-Undang Nomor 28 tahun 2000 tentang usaha dan peran masyarakat Jasa Konstruksi (Lembaran Negara Republik Indonesia tahun 2000 Nomor 63);\"},\"2\":{\"isi\":\"Undang-Undang Nomor 7 Tahun 2003 tentang Pembentukan Kabupaten Luwu Timur dan Kabupaten Mamuju Utara di Provinsi Sulawesi Selatan (Lembaran Negara Tahun 2003 Nomor 27, Tambahan Lembaran NegaraNomor 4270);\"},\"3\":{\"isi\":\"Undang-Undang Nomor 17 Tahun 2003 tentang Keuangan Negara (Lembaran Negara Republik Indonesia Tahun 2003 Nomor 47, Tambahan Lembaran Negara Republik Indonesia Nomor 4286);\"},\"4\":{\"isi\":\"Undang-Undang Nomor 1 Tahun 2004 tentang Perbendaharaan Negara (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 5, Tambahan Lembaran Negara Republik Indonesia Nomor 4355);\"},\"5\":{\"isi\":\"Undang-Undang Nomor 33 Tahun 2004 tentang Perimbangan Keuangan Antara Pemerintah Pusat dan Pemerintah Daerah (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 126, Tambahan Lembaran Negara Republik Indonesia Nomor 4438);\"},\"6\":{\"isi\":\"Undang-Undang Nomor 2 Tahun 2017 tentang Jasa Konstruksi;\"},\"7\":{\"isi\":\"Peraturan Presiden Republik Indonesia Nomor 16 Tahun 2019 tentang Pengadaan Barang/Jasa Pemerintah;\"},\"8\":{\"isi\":\"Peraturan Pemerintah Nomor 61 Tahun 2017 tentang Perubahan Nama Kabupaten Mamuju Utara menjadi Kabupaten Pasangkayu di Provinsi Sulawesi Barat (Lembaran Negara Republik Indonesia Tahun 2017 Nomor 312, Tambahan Lembaran Negara Republik Indonesia Nomor 6715);\"},\"9\":{\"isi\":\"Peraturan Menteri Dalam Negeri Nomor 13 Tahun 2006 tentang Pedoman Pengelolaan Keuangan Daerah sebagaimana telah diubah dengan Peraturan Menteri Dalam Negeri Nomor 59 Tahun 2007 tentang Perubahan Atas Peraturan Menteri Dalam Negeri Nomor 13 Tahun 2006 tentang Pedoman Pengelolaan Keuangan Daerah;\"},\"10\":{\"isi\":\"Peraturan Menteri Dalam Negeri Nomor 27 Tahun 2021 tentang Pedoman Penyusunan Anggaran Pendapatan dan Belanja Daerah Tahun Anggaran 2022;\"},\"11\":{\"isi\":\"Peraturan Daerah Kabupaten Mamuju Utara Nomor 5 Tahun 2006 tentang pokok-pokok Pengelolaan Keuangan Daerah (Lembaran Daerah Nomor 5 Tahun 2006, Tambahan Lembaran Daerah Nomor 5);\"},\"12\":{\"isi\":\"Peraturan Daerah Kabupaten Pasangkayu Nomor 7 Tahun 2021 tanggal 30 Desember 2021 tentang Anggaran pendapatan dan Belanja Daerah Tahun Anggaran 2022;\"},\"13\":{\"isi\":\"Peraturan Bupati Kabupaten Pasangkayu Nomor 34 Tahun 2021 tanggal 31 Desember 2021 tentang Penjabaran Anggaran Pendapatan dan Belanja Daerah Kebupaten Pasangkayu Tahun Anggaran 2022.\"}}', '{\"0\":{\"isi\":\"Tugas Pejabat sebagaimana dimaksud pada diktum Kesatu adalah :\",\"p_l\":\"P\"},\"1\":{\"isi\":\"Mengendalikan pelaksanaan kegiatan;\",\"p_l\":\"L\"},\"2\":{\"isi\":\"Melaporkan perkembangan pelaksanaan kegiatan;\",\"p_l\":\"L\"},\"3\":{\"isi\":\"Menyiapkan dokumen anggaran atas beban pengeluaran pelaksanaan kegiatan;dan\",\"p_l\":\"L\"},\"4\":{\"isi\":\"Membantu Pejabat Pembuat Komitmen dalam melaksanakan tugasnya.\",\"p_l\":\"L\"}}', '{\"0\":{\"isi\":\"Segala biaya yang timbul akibat keputusan ini dibebankan kepada Pos Anggaran Dinas Pekerjaan Umum dan Penataan Ruang Kabupaten Pasangkayu Tahun Anggaran 2023.\",\"p_l\":\"P\"}}', '{\"0\":{\"isi\":\"Keputusan ini mulai berlaku pada tanggal ditetapkan dan apabila terdapat kekeliruan didalamnya akan diperbaharui sebagaimana mestinya.\",\"p_l\":\"P\"}}', '{}', '{\"0\":{\"tembusan\":\"Bupati                                            Pasangkayu, di Pasangkayu\"},\"1\":{\"tembusan\":\"Sekretaris Daerah Kabupaten Pasangkayu di Pasangkayu\"},\"2\":{\"tembusan\":\"Inspektur Inspektorat Kabupaten Pasangkayu di Pasangkayu\"},\"3\":{\"tembusan\":\"Kepala Badan PKAD Kabupaten Pasangkayu di Pasangkayu\"},\"4\":{\"tembusan\":\"Masing-masing yang bersangkutan\"},\"5\":{\"tembusan\":\"Pertinggal\"}}', '', '', '0000-00-00 00:00:00', '', '0000-00-00 00:00:00', '', 0, 0),
(70, '2023', '76.01', '1.03.0.00.0.00.01.0000', '06 TAHUN 2023', '2023-01-11', 'pengangkatan pejabat pengadaan barang / jasa pemerintah pada dinas pekerjaan umum dan penataan ruang kabupaten pasangkayu tahun 2023', '198006152006041018', 'kepala', 'Pembina Tingkat I, IV/b', 'Sumarlin, ST, M.AP', '{\"0\":{\"nama\":\"Alwi Mansyur, A.Md\",\"pangkat\":\"Penata Muda, III/b\",\"nip\":\"198007112006041010\",\"jabatan\":\"Verifikator Keuangan\",\"jabatan_sk\":\"Pejabat Pengadaan Dinas Pekerjaan Umum dan Penataan Ruang Kab. Pasangkayu\"}}', 0, '{\"0\":{\"isi\":\"bahwa untuk pelaksanaan proses kerja pengelolaan Barang / Jasa yang efektif, efisien dan akuntabel pada Dinas Pekerjaan Umum dan Penataan Ruang Pemerintah Daerah Kabupaten Pasangkayu, maka dipandang perlu mengangkat Pejabat Pengadaan Barang / Jasa pada Dinas Pekerjaan Umum dan Penataan Ruang Kabupaten Pasangkayu\"},\"1\":{\"isi\":\"bahwa yang tersebut namanya dalam lampiran keputusan ini dipandang cakap dan mampu melaksanakan tugas\"},\"2\":{\"isi\":\"bahwa pengangkatan sebagaimana dimaksud pada point a perlu ditetapkan dalam Keputusan Kepala Dinas\"}}', '{\"0\":{\"isi\":\"Undang-Undang Nomor 28 Tahun 1999 tentang Penyelenggaraan Pemerintahan yang bersih dan bebas Korupsi, Kolusi dan Nepotisme (Lembaran Negara Republik Indonesia Tahun 1999 Nomor 75, Tambahan Lembaran Negara Republik Indonesia Nomor 3581);\"},\"1\":{\"isi\":\"Undang-Undang Nomor 28 tahun 2000 tentang usaha dan peran masyarakat Jasa Konstruksi (Lembaran Negara Republik Indonesia tahun 2000 Nomor 63);\"},\"2\":{\"isi\":\"Undang-Undang Nomor 7 Tahun 2003 tentang Pembentukan Kabupaten Luwu Timur dan Kabupaten Mamuju Utara di Provinsi Sulawesi Selatan (Lembaran Negara Tahun 2003 Nomor 27, Tambahan Lembaran Negara Nomor 4270);\"},\"3\":{\"isi\":\"Undang-Undang Nomor 17 Tahun 2003 tentang Keuangan Negara (Lembaran Negara Republik Indonesia Tahun 2003 Nomor 47, Tambahan Lembaran Negara Republik Indonesia Nomor 4286);\"},\"4\":{\"isi\":\"Undang-Undang Nomor 1 Tahun 2004 tentang Perbendaharaan Negara (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 5, Tambahan Lembaran Negara Republik Indonesia Nomor 4355);\"},\"5\":{\"isi\":\"Undang-Undang Nomor 32 Tahun 2004 tentang Pemerintahan Daerah (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 125, Tambahan Lembaran Negara Republik Indonesia Nomor 4437) sebagaimana telah diubah dengan Undang-Undang Nomor 8 Tahun 2005 tentang Penetapan Peraturan Pemerintah Pengganti Undang-Undang Nomor 3 Tahun 2005 tentang Perubahan Undang-Undang Nomor 32 Tahun 2004 tentang Pemerintahan Daerah menjadi Undang-Undang (Lembaran Negara Republik Indonesia Tahun 2005 Nomor 108, Tambahan Lembaran Negara Republik Indonesia Nomor 4548);\"},\"6\":{\"isi\":\"Undang-Undang Nomor 33 Tahun 2004 tentang Perimbangan Keuangan Antara Pemerintah Pusat dan Pemerintah Daerah (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 126, Tambahan Lembaran Negara Republik Indonesia Nomor 4438);\"},\"7\":{\"isi\":\"Undang-Undang Nomor 2 Tahun 2017 tentang Jasa Konstruksi;\"},\"8\":{\"isi\":\"Peraturan Presiden Republik Indonesia Nomor 12 Tahun 2021 tentang Pengadaan Barang/Jasa Pemerintah;\"},\"9\":{\"isi\":\"Peraturan Menteri Dalam Negeri Nomor 77 Tahun 2020 tentang Pedoman Teknis Pengelolaan Keuangan Daerah;\"},\"10\":{\"isi\":\"Peraturan Menteri Dalam Negeri Nomor 84 Tahun 2022 tentang Pedoman Penyusunan Anggaran Pendapatan dan Belanja Daerah Tahun Anggaran 2023;\"},\"11\":{\"isi\":\"Peraturan Daerah Kabupaten Pasangkayu Nomor 5 Tahun 2022 tanggal 30 Desember 2022 tentang Anggaran pendapatan dan Belanja Daerah Tahun Anggaran 2023;\"},\"12\":{\"isi\":\"Peraturan Bupati Kabupaten Pasangkayu Nomor 33 Tahun 2022 tanggal 30 Desember 2022 tentang Penjabaran Anggaran Pendapatan dan Belanja Daerah Kebupaten Pasangkayu Tahun Anggaran 2023.\"}}', '{\"0\":{\"isi\":\"Tugas Pejabat sebagaimana dimaksud pada diktum Kesatu adalah :\",\"p_l\":\"P\"},\"1\":{\"isi\":\"melaksanakan persiapan dan pelaksanaan Pengadaan Langsung;\",\"p_l\":\"L\"},\"2\":{\"isi\":\"melaksanakan persiapan dan pelaksanaan Penunjukan Langsung untuk pengadaan Barang/Pekerjaan Konstruksi/Jasa Lainnya yang bernilai paling banyak Rp200.000.000,00 (dua ratus juta rupiah);\",\"p_l\":\"L\"},\"3\":{\"isi\":\"melaksanakan persiapan dan pelaksanaan Penunjukan Langsung untuk pengadaan Jasa Konsultansi yang bernilai paling banyak Rp100.000.000,00 (seratus juta rupiah);\",\"p_l\":\"L\"},\"4\":{\"isi\":\"melaksanakan E-purchasing yang bernilai paling banyak Rp200.000.000,00 (dua ratus juta rupiah);\",\"p_l\":\"L\"},\"5\":{\"isi\":\"Menyerahkan dokumen asli pemilihan penyedia barang / jasa Pemerintah kepada pengguna anggaran;\",\"p_l\":\"L\"},\"6\":{\"isi\":\"Membuat laporan mengenai proses dan hasil pengadaan kepada pengguna anggaran; dan\",\"p_l\":\"L\"},\"7\":{\"isi\":\"Memberikan pertanggungjawaban atas pelaksanaan kegiatan pengadaan barang / jasa Konstruksi kepada pengguna anggaran\",\"p_l\":\"L\"}}', '{\"0\":{\"isi\":\"Segala biaya yang timbul akibat keputusan ini dibebankan kepada Pos Anggaran Dinas Pekerjaan Umum dan Penataan Ruang Kabupaten Pasangkayu Tahun Anggaran 2023\",\"p_l\":\"P\"}}', '{\"0\":{\"isi\":\"Keputusan ini mulai berlaku pada tanggal ditetapkan dan apabila terdapat kekeliruan didalamnya akan diperbaharui sebagaimana mestinya\",\"p_l\":\"P\"}}', '{}', '{\"0\":{\"tembusan\":\"Bupati                                            Pasangkayu, di Pasangkayu\"},\"1\":{\"tembusan\":\"Sekretaris Daerah Kabupaten Pasangkayu di Pasangkayu\"},\"2\":{\"tembusan\":\"Inspektur Inspektorat Kabupaten Pasangkayu di Pasangkayu\"},\"3\":{\"tembusan\":\"Kepala Badan PKAD Kabupaten Pasangkayu di Pasangkayu\"},\"4\":{\"tembusan\":\"Masing-masing yang bersangkutan\"},\"5\":{\"tembusan\":\"Pertinggal\"}}', '', '', '0000-00-00 00:00:00', '', '0000-00-00 00:00:00', '', 0, 0);
INSERT INTO `sk_asn_neo` (`id`, `tahun`, `kd_wilayah`, `kd_opd`, `nomor`, `tgl_surat_dibuat`, `tentang`, `pemberi_tgs`, `jbt_pemberi_tgs`, `pangkat_pemberi_tgs`, `nama_pemberi_tgs`, `nama_ditugaskan`, `bentuk_lampiran`, `menimbang`, `mengingat`, `menetapkan_1`, `menetapkan_2`, `menetapkan_3`, `menetapkan_4`, `tembusan`, `file`, `keterangan`, `tgl_insert`, `username_insert`, `tgl_update`, `username_update`, `disable`, `is_deleted`) VALUES
(71, '2023', '76.01', '1.03.0.00.0.00.01.0000', '15 TAHUN 2023', '2023-01-11', 'pengangkatan penjaga kantor dinas pekerjaan umum dan penataan ruang kabupaten pasangkayu tahun 2023', '198006152006041018', 'kepala', 'Pembina Tingkat I, IV/b', 'Sumarlin, ST, M.AP', '{\"0\":{\"nama\":\"Adiyansa\",\"pangkat\":\"-\",\"nip\":\"-\",\"jabatan\":\"non asn\",\"jabatan_sk\":\"penjaga kantor\"},\"1\":{\"nama\":\"Budiman\",\"pangkat\":\"-\",\"nip\":\"-\",\"jabatan\":\"non asn\",\"jabatan_sk\":\"penjaga kantor\"}}', 0, '{\"0\":{\"isi\":\"bahwa untuk keamanan aset kantor pada Dinas Pekerjaan Umum dan Penataan Ruang Pemerintah Daerah Kabupaten Pasangkayu, maka dipandang perlu mengangkat Penjaga Kantor Dinas Pekerjaan Umum Kabupaten Pasangkayu Tahun 2023;\"},\"1\":{\"isi\":\"bahwa yang tersebut namanya dalam lampiran keputusan ini dipandang cakap dan mampu melaksanakan tugas;\"},\"2\":{\"isi\":\"bahwa pengangkatan sebagaimana dimaksud pada point a perlu ditetapkan dalam Keputusan Kepala Dinas.\"}}', '{\"0\":{\"isi\":\"Undang-Undang Nomor 28 Tahun 1999 tentang Penyelenggaraan Pemerintahan yang bersih dan bebas Korupsi, Kolusi dan Nepotisme (Lembaran Negara Republik Indonesia Tahun 1999 Nomor 75, Tambahan Lembaran Negara Republik Indonesia Nomor 3581);\"},\"1\":{\"isi\":\"Undang-Undang Nomor 28 tahun 2000 tentang usaha dan peran masyarakat Jasa Konstruksi (Lembaran Negara Republik Indonesia tahun 2000 Nomor 63);\"},\"2\":{\"isi\":\"Undang-Undang Nomor 7 Tahun 2003 tentang Pembentukan Kabupaten Luwu Timur dan Kabupaten Mamuju Utara di Provinsi Sulawesi Selatan (Lembaran Negara Tahun 2003 Nomor 27, Tambahan Lembaran Negara Nomor 4270);\"},\"3\":{\"isi\":\"Undang-Undang Nomor 17 Tahun 2003 tentang Keuangan Negara (Lembaran Negara Republik Indonesia Tahun 2003 Nomor 47, Tambahan Lembaran Negara Republik Indonesia Nomor 4286);\"},\"4\":{\"isi\":\"Undang-Undang Nomor 1 Tahun 2004 tentang Perbendaharaan Negara (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 5, Tambahan Lembaran Negara Republik Indonesia Nomor 4355);\"},\"5\":{\"isi\":\"Undang-Undang Nomor 32 Tahun 2004 tentang Pemerintahan Daerah (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 125, Tambahan Lembaran Negara Republik Indonesia Nomor 4437) sebagaimana telah diubah dengan Undang-Undang Nomor 8 Tahun 2005 tentang Penetapan Peraturan Pemerintah Pengganti Undang-Undang Nomor 3 Tahun 2005 tentang Perubahan Undang-Undang Nomor 32 Tahun 2004 tentang Pemerintahan Daerah menjadi Undang-Undang (Lembaran Negara Republik Indonesia Tahun 2005 Nomor 108, Tambahan Lembaran Negara Republik Indonesia Nomor 4548);\"},\"6\":{\"isi\":\"Undang-Undang Nomor 33 Tahun 2004 tentang Perimbangan Keuangan Antara Pemerintah Pusat dan Pemerintah Daerah (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 126, Tambahan Lembaran Negara Republik Indonesia Nomor 4438);\"},\"7\":{\"isi\":\"Peraturan Menteri Dalam Negeri Nomor 77 Tahun 2020 tentang Pedoman Teknis Pengelolaan Keuangan Daerah;\"},\"8\":{\"isi\":\"Peraturan Menteri Dalam Negeri Nomor 84 Tahun 2022 tentang Pedoman Penyusunan Anggaran Pendapatan dan Belanja Daerah Tahun Anggaran 2023;\"},\"9\":{\"isi\":\"Peraturan Daerah Kabupaten Mamuju Utara Nomor 5 Tahun 2006 tentang pokok-pokok Pengelolaan Keuangan Daerah (Lembaran Daerah Nomor 5 Tahun 2006, Tambahan Lembaran Daerah Nomor 5);\"},\"10\":{\"isi\":\"Peraturan Daerah Kabupaten Pasangkayu Nomor 35 Tahun 2016 tentang Pembentukan Organisasi Perangkat Daerah;\"},\"11\":{\"isi\":\"Peraturan Daerah Kabupaten Pasangkayu Nomor 5 Tahun 2022 tanggal 30 Desember 2022 tentang Anggaran pendapatan dan Belanja Daerah Tahun Anggaran 2023;\"},\"12\":{\"isi\":\"Peraturan Bupati Kabupaten Pasangkayu Nomor 33 Tahun 2022 tanggal 30 Desember 2022 tentang Penjabaran Anggaran Pendapatan dan Belanja Daerah Kebupaten Pasangkayu Tahun Anggaran 2023.\"}}', '{\"0\":{\"isi\":\"Tugas Pejabat sebagaimana dimaksud pada diktum Kesatu adalah :\",\"p_l\":\"P\"},\"1\":{\"isi\":\"Melaksanakan Pengamanan secara menyeluruh di lokasi kerja, baik perkantoran dan lingkungan untuk memastikan kondisi keamanan kantor;\",\"p_l\":\"L\"},\"2\":{\"isi\":\"Melakukan pemeriksaan pada tamu / pemilik yang akan masuk ke area kantor/kerja terutama malam hari ;\",\"p_l\":\"L\"},\"3\":{\"isi\":\"Menyalakan dan Mematikan lampu Setelah Jaga malam;\",\"p_l\":\"L\"},\"4\":{\"isi\":\"Mengecek Kunci-kunci pintu, jendela dan pagar kantor\",\"p_l\":\"L\"},\"5\":{\"isi\":\"Membuat Laporan penting kejadian-kejadian penting selama masa penjagaan pada buku laporan\",\"p_l\":\"L\"}}', '{\"0\":{\"isi\":\"Segala biaya yang timbul akibat keputusan ini dibebankan kepada Pos Anggaran Dinas Pekerjaan Umum dan Penataan Ruang Kabupaten Pasangkayu Tahun Anggaran 2023.\",\"p_l\":\"P\"}}', '{\"0\":{\"isi\":\"Keputusan ini mulai berlaku pada tanggal ditetapkan dan apabila terdapat kekeliruan didalamnya akan diperbaharui sebagaimana mestinya.\",\"p_l\":\"P\"}}', '{}', '{\"0\":{\"tembusan\":\"Bupati                                            Pasangkayu, di Pasangkayu\"},\"1\":{\"tembusan\":\"Sekretaris Daerah Kabupaten Pasangkayu di Pasangkayu\"},\"2\":{\"tembusan\":\"Inspektur Inspektorat Kabupaten Pasangkayu di Pasangkayu\"},\"3\":{\"tembusan\":\"Kepala Badan PKAD Kabupaten Pasangkayu di Pasangkayu\"},\"4\":{\"tembusan\":\"Masing-masing yang bersangkutan\"},\"5\":{\"tembusan\":\"Pertinggal\"}}', '', '', '0000-00-00 00:00:00', '', '0000-00-00 00:00:00', '', 0, 0),
(72, '2023', '76.01', '1.03.0.00.0.00.01.0000', '15 TAHUN 2023', '2023-01-11', 'pengangkatan Pengantar/administrasi surat-menyurat dinas pekerjaan umum dan penataan ruang kabupaten pasangkayu tahun 2023', '198006152006041018', 'kepala', 'Pembina Tingkat I, IV/b', 'Sumarlin, ST, M.AP', '{\"0\":{\"nama\":\"Syahrul Ramadhan Hairun\",\"pangkat\":\"-\",\"nip\":\"-\",\"jabatan\":\"honorer\",\"jabatan_sk\":\"administrasi surat penyurat\"},\"1\":{\"nama\":\"Sirajuddin\",\"pangkat\":\"-\",\"nip\":\"-\",\"jabatan\":\"honorer\",\"jabatan_sk\":\"administrasi surat penyurat\"}}', 0, '{\"0\":{\"isi\":\"bahwa untuk kelancaran pelaksanaan administrasi dokumen persuratan yang baik pada Dinas Pekerjaan Umum dan Penataan Ruang Pemerintah Daerah Kabupaten Pasangkayu, maka dipandang perlu mengangkat Pengantar Surat pada Dinas Pekerjaan Umum Kabupaten Pasangkayu;\"},\"1\":{\"isi\":\"bahwa yang tersebut namanya dalam lampiran keputusan ini dipandang cakap dan mampu melaksanakan tugas;\"},\"2\":{\"isi\":\"bahwa pengangkatan sebagaimana dimaksud pada point a perlu ditetapkan dalam Keputusan Kepala Dinas.\"}}', '{\"0\":{\"isi\":\"Undang-Undang Nomor 28 Tahun 1999 tentang Penyelenggaraan Pemerintahan yang bersih dan bebas Korupsi, Kolusi dan Nepotisme (Lembaran Negara Republik Indonesia Tahun 1999 Nomor 75, Tambahan Lembaran Negara Republik Indonesia Nomor 3581);\"},\"1\":{\"isi\":\"Undang-Undang Nomor 28 tahun 2000 tentang usaha dan peran masyarakat Jasa Konstruksi (Lembaran Negara Republik Indonesia tahun 2000 Nomor 63);\"},\"2\":{\"isi\":\"Undang-Undang Nomor 7 Tahun 2003 tentang Pembentukan Kabupaten Luwu Timur dan Kabupaten Mamuju Utara di Provinsi Sulawesi Selatan (Lembaran Negara Tahun 2003 Nomor 27, Tambahan Lembaran Negara Nomor 4270);\"},\"3\":{\"isi\":\"Undang-Undang Nomor 17 Tahun 2003 tentang Keuangan Negara (Lembaran Negara Republik Indonesia Tahun 2003 Nomor 47, Tambahan Lembaran Negara Republik Indonesia Nomor 4286);\"},\"4\":{\"isi\":\"Undang-Undang Nomor 1 Tahun 2004 tentang Perbendaharaan Negara (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 5, Tambahan Lembaran Negara Republik Indonesia Nomor 4355);\"},\"5\":{\"isi\":\"Undang-Undang Nomor 32 Tahun 2004 tentang Pemerintahan Daerah (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 125, Tambahan Lembaran Negara Republik Indonesia Nomor 4437) sebagaimana telah diubah dengan Undang-Undang Nomor 8 Tahun 2005 tentang Penetapan Peraturan Pemerintah Pengganti Undang-Undang Nomor 3 Tahun 2005 tentang Perubahan Undang-Undang Nomor 32 Tahun 2004 tentang Pemerintahan Daerah menjadi Undang-Undang (Lembaran Negara Republik Indonesia Tahun 2005 Nomor 108, Tambahan Lembaran Negara Republik Indonesia Nomor 4548);\"},\"6\":{\"isi\":\"Undang-Undang Nomor 33 Tahun 2004 tentang Perimbangan Keuangan Antara Pemerintah Pusat dan Pemerintah Daerah (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 126, Tambahan Lembaran Negara Republik Indonesia Nomor 4438);\"},\"7\":{\"isi\":\"Peraturan Menteri Dalam Negeri Nomor 77 Tahun 2020 tentang Pedoman Teknis Pengelolaan Keuangan Daerah;\"},\"8\":{\"isi\":\"Peraturan Menteri Dalam Negeri Nomor 84 Tahun 2022 tentang Pedoman Penyusunan Anggaran Pendapatan dan Belanja Daerah Tahun Anggaran 2023;\"},\"9\":{\"isi\":\"Peraturan Daerah Kabupaten Mamuju Utara Nomor 5 Tahun 2006 tentang pokok-pokok Pengelolaan Keuangan Daerah (Lembaran Daerah Nomor 5 Tahun 2006, Tambahan Lembaran Daerah Nomor 5);\"},\"10\":{\"isi\":\"Peraturan Daerah Kabupaten Pasangkayu Nomor 35 Tahun 2016 tentang Pembentukan Organisasi Perangkat Daerah;\"},\"11\":{\"isi\":\"Peraturan Daerah Kabupaten Pasangkayu Nomor 5 Tahun 2022 tanggal 30 Desember 2022 tentang Anggaran pendapatan dan Belanja Daerah Tahun Anggaran 2023;\"},\"12\":{\"isi\":\"Peraturan Bupati Kabupaten Pasangkayu Nomor 33 Tahun 2022 tanggal 30 Desember 2022 tentang Penjabaran Anggaran Pendapatan dan Belanja Daerah Kebupaten Pasangkayu Tahun Anggaran 2023.\"}}', '{\"0\":{\"isi\":\"Tugas Personil sebagaimana dimaksud pada diktum Kesatu adalah sebagai berikut :\",\"p_l\":\"P\"},\"1\":{\"isi\":\"Menerima dan mempelajari surat;\",\"p_l\":\"L\"},\"2\":{\"isi\":\"Menyortir surat menurut jenis dan sifatnya;\",\"p_l\":\"L\"},\"3\":{\"isi\":\"Mencatat dan mengendalikan surat;\",\"p_l\":\"L\"},\"4\":{\"isi\":\"Mengantar dan memberi lembar pengantar surat/ekspedisi;\",\"p_l\":\"L\"},\"5\":{\"isi\":\"Mendokumentasikan surat;\",\"p_l\":\"L\"},\"6\":{\"isi\":\"Melaporkan hasil pelaksanaan tugas secara tertulis dan lisan kepada atasan sesuai prosedur yang berlaku;\",\"p_l\":\"L\"},\"7\":{\"isi\":\"Melaksanakan tugas kedinasan lain yang diperintahkan pimpinan baik tertulis maupun lisan.\",\"p_l\":\"L\"}}', '{\"0\":{\"isi\":\"Segala biaya yang timbul akibat keputusan ini dibebankan kepada Pos Anggaran Dinas Pekerjaan Umum dan Penataan Ruang Kabupaten Pasangkayu Tahun Anggaran 2023.\",\"p_l\":\"P\"}}', '{\"0\":{\"isi\":\"Keputusan ini mulai berlaku pada tanggal ditetapkan dan apabila terdapat kekeliruan didalamnya akan diperbaharui sebagaimana mestinya;\",\"p_l\":\"L\"}}', '{}', '{\"0\":{\"tembusan\":\"Bupati                                            Pasangkayu, di Pasangkayu\"},\"1\":{\"tembusan\":\"Sekretaris Daerah Kabupaten Pasangkayu di Pasangkayu\"},\"2\":{\"tembusan\":\"Inspektur Inspektorat Kabupaten Pasangkayu di Pasangkayu\"},\"3\":{\"tembusan\":\"Kepala Badan PKAD Kabupaten Pasangkayu di Pasangkayu\"},\"4\":{\"tembusan\":\"Masing-masing yang bersangkutan\"},\"5\":{\"tembusan\":\"Pertinggal\"}}', '', '', '0000-00-00 00:00:00', '', '0000-00-00 00:00:00', '', 0, 0),
(73, '2023', '76.01', '1.03.0.00.0.00.01.0000', '11 TAHUN 2023', '2023-01-11', 'pengangkatan sopir kantor dinas pekerjaan umum dan penataan ruang kabupaten pasangkayu tahun 2023', '198006152006041018', 'kepala', 'Pembina Tingkat I, IV/b', 'Sumarlin, ST, M.AP', '{\"0\":{\"nama\":\"M. IRWAN\",\"pangkat\":\"Non ASN\",\"nip\":\"Non ASN\",\"jabatan\":\"Honorer\",\"jabatan_sk\":\"Sopir Dinas Pekerjaan Umum dan Penataan Ruang Kab. Pasangkayu\"}}', 0, '{\"0\":{\"isi\":\"bahwa untuk kelancaran pelaksanaan perkantoran yang baik pada Dinas Pekerjaan Umum dan Penataan Ruang Pemerintah Daerah Kabupaten Pasangkayu, maka dipandang perlu mengangkat sopir pada Dinas Pekerjaan Umum Kabupaten Pasangkayu;\"},\"1\":{\"isi\":\"bahwa yang tersebut namanya dalam lampiran keputusan ini dipandang cakap dan mampu melaksanakan tugas;\"},\"2\":{\"isi\":\"bahwa pengangkatan sebagaimana dimaksud pada point a perlu ditetapkan dalam Keputusan Kepala Dinas.\"}}', '{\"0\":{\"isi\":\"Undang-Undang Nomor 28 Tahun 1999 tentang Penyelenggaraan Pemerintahan yang bersih dan bebas Korupsi, Kolusi dan Nepotisme (Lembaran Negara Republik Indonesia Tahun 1999 Nomor 75, Tambahan Lembaran Negara Republik Indonesia Nomor 3581);\"},\"1\":{\"isi\":\"Undang-Undang Nomor 28 tahun 2000 tentang usaha dan peran masyarakat Jasa Konstruksi (Lembaran Negara Republik Indonesia tahun 2000 Nomor 63);\"},\"2\":{\"isi\":\"Undang-Undang Nomor 7 Tahun 2003 tentang Pembentukan Kabupaten Luwu Timur dan Kabupaten Mamuju Utara di Provinsi Sulawesi Selatan (Lembaran Negara Tahun 2003 Nomor 27, Tambahan Lembaran NegaraNomor 4270);\"},\"3\":{\"isi\":\"Undang-Undang Nomor 17 Tahun 2003 tentang Keuangan Negara (Lembaran Negara Republik Indonesia Tahun 2003 Nomor 47, Tambahan Lembaran Negara Republik Indonesia Nomor 4286);\"},\"4\":{\"isi\":\"Undang-Undang Nomor 1 Tahun 2004 tentang Perbendaharaan Negara (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 5, Tambahan Lembaran Negara Republik Indonesia Nomor 4355);\"},\"5\":{\"isi\":\"Undang-Undang Nomor 33 Tahun 2004 tentang Perimbangan Keuangan Antara Pemerintah Pusat dan Pemerintah Daerah (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 126, Tambahan Lembaran Negara Republik Indonesia Nomor 4438);\"},\"6\":{\"isi\":\"Undang-Undang Nomor 2 Tahun 2017 tentang Jasa Konstruksi;\"},\"7\":{\"isi\":\"Peraturan Pemerintah Nomor 61 Tahun 2017 tentang Perubahan Nama Kabupaten Mamuju Utara menjadi Kabupaten Pasangkayu di Provinsi Sulawesi Barat (Lembaran Negara Republik Indonesia Tahun 2017 Nomor 312, Tambahan Lembaran Negara Republik Indonesia Nomor 6715);\"},\"8\":{\"isi\":\"Peraturan Menteri Dalam Negeri Nomor 13 Tahun 2006 tentang Pedoman Pengelolaan Keuangan Daerah sebagaimana telah diubah dengan Peraturan Menteri Dalam Negeri Nomor 59 Tahun 2007 tentang Perubahan Atas Peraturan Menteri Dalam Negeri Nomor 13 Tahun 2006 tentang Pedoman Pengelolaan Keuangan Daerah;\"},\"9\":{\"isi\":\"Peraturan Menteri Dalam Negeri Nomor 84 Tahun 2022 tentang Pedoman Penyusunan Anggaran Pendapatan dan Belanja Daerah Tahun Anggaran 2023;\"},\"10\":{\"isi\":\"Peraturan Daerah Kabupaten Pasangkayu Nomor 5 Tahun 2022 tanggal 30 Desember 2022 tentang Anggaran pendapatan dan Belanja Daerah Tahun Anggaran 2023;\"},\"11\":{\"isi\":\"Peraturan Bupati Kabupaten Pasangkayu Nomor 33 Tahun 2022 tanggal 30 Desember 2022 tentang Penjabaran Anggaran Pendapatan dan Belanja Daerah Kebupaten Pasangkayu Tahun Anggaran 2023.\"}}', '{\"0\":{\"isi\":\"Tugas Personil sebagaimana dimaksud penetapan adalah sebagai berikut :\",\"p_l\":\"P\"},\"1\":{\"isi\":\"Memeriksa kelengkapan kendaraan;\",\"p_l\":\"L\"},\"2\":{\"isi\":\"Mengantarkan pimpinan dalam melaksanakan tugas sesuai dengan perintah;\",\"p_l\":\"L\"},\"3\":{\"isi\":\"Membersihkan Mobil/kendaraan dinas;\",\"p_l\":\"L\"},\"4\":{\"isi\":\"Melakukan service dan penggantian suku cadang yang sudah rusak dibengkel;\",\"p_l\":\"L\"}}', '{\"0\":{\"isi\":\"Segala biaya yang timbul akibat keputusan ini dibebankan kepada Pos Anggaran Dinas Pekerjaan Umum dan Penataan Ruang Kabupaten Pasangkayu Tahun Anggaran 2023.\",\"p_l\":\"P\"}}', '{\"0\":{\"isi\":\"Keputusan ini mulai berlaku pada tanggal ditetapkan dan apabila terdapat kekeliruan didalamnya akan diperbaharui sebagaimana mestinya.\",\"p_l\":\"P\"}}', '{}', '{\"0\":{\"tembusan\":\"Bupati                                            Pasangkayu, di Pasangkayu\"},\"1\":{\"tembusan\":\"Sekretaris Daerah Kabupaten Pasangkayu di Pasangkayu\"},\"2\":{\"tembusan\":\"Inspektur Inspektorat Kabupaten Pasangkayu di Pasangkayu\"},\"3\":{\"tembusan\":\"Kepala Badan PKAD Kabupaten Pasangkayu di Pasangkayu\"},\"4\":{\"tembusan\":\"Masing-masing yang bersangkutan\"},\"5\":{\"tembusan\":\"Pertinggal\"}}', '', '', '0000-00-00 00:00:00', '', '0000-00-00 00:00:00', '', 0, 0),
