(101, '2024', '76.01', '1.03.0.00.0.00.01.0000', '15 TAHUN 2024', '2024-01-08', 'pengangkatan penjaga kantor dinas pekerjaan umum dan penataan ruang kabupaten pasangkayu tahun 2024', '198006152006041018', 'kepala', 'Pembina Tingkat I, IV/b', 'Sumarlin, ST, M.AP', '{\"0\":{\"nama\":\"Adiyansa\",\"pangkat\":\"-\",\"nip\":\"-\",\"jabatan\":\"non asn\",\"jabatan_sk\":\"penjaga kantor\"},\"1\":{\"nama\":\"Budiman\",\"pangkat\":\"-\",\"nip\":\"-\",\"jabatan\":\"non asn\",\"jabatan_sk\":\"penjaga kantor\"}}', 0, '{\"0\":{\"isi\":\"bahwa untuk keamanan aset kantor pada Dinas Pekerjaan Umum dan Penataan Ruang Pemerintah Daerah Kabupaten Pasangkayu, maka dipandang perlu mengangkat Penjaga Kantor Dinas Pekerjaan Umum Kabupaten Pasangkayu Tahun 2023;\"},\"1\":{\"isi\":\"bahwa yang tersebut namanya dalam lampiran keputusan ini dipandang cakap dan mampu melaksanakan tugas;\"},\"2\":{\"isi\":\"bahwa pengangkatan sebagaimana dimaksud pada point a perlu ditetapkan dalam Keputusan Kepala Dinas.\"}}', '{\"0\":{\"isi\":\"Undang-Undang Nomor 28 Tahun 1999 tentang Penyelenggaraan Pemerintahan yang bersih dan bebas Korupsi, Kolusi dan Nepotisme (Lembaran Negara Republik Indonesia Tahun 1999 Nomor 75, Tambahan Lembaran Negara Republik Indonesia Nomor 3581);\"},\"1\":{\"isi\":\"Undang-Undang Nomor 28 tahun 2000 tentang usaha dan peran masyarakat Jasa Konstruksi (Lembaran Negara Republik Indonesia tahun 2000 Nomor 63);\"},\"2\":{\"isi\":\"Undang-Undang Nomor 7 Tahun 2003 tentang Pembentukan Kabupaten Luwu Timur dan Kabupaten Mamuju Utara di Provinsi Sulawesi Selatan (Lembaran Negara Tahun 2003 Nomor 27, Tambahan Lembaran Negara Nomor 4270);\"},\"3\":{\"isi\":\"Undang-Undang Nomor 17 Tahun 2003 tentang Keuangan Negara (Lembaran Negara Republik Indonesia Tahun 2003 Nomor 47, Tambahan Lembaran Negara Republik Indonesia Nomor 4286);\"},\"4\":{\"isi\":\"Undang-Undang Nomor 1 Tahun 2022 tentang Hubungan Keuangan Antara Pemerintah Pusat dan Pemerintah Daerah;\"},\"5\":{\"isi\":\"Undang-Undang Nomor 2 Tahun 2017 tentang Jasa Konstruksi;\"},\"6\":{\"isi\":\"Peraturan Pemerintah Nomor 61 Tahun 2017 tentang Perubahan Nama Kabupaten Mamuju Utara menjadi Kabupaten Pasangkayu di Provinsi Sulawesi Barat (Lembaran Negara Republik Indonesia Tahun 2017 Nomor 312, Tambahan Lembaran Negara Republik Indonesia Nomor 6715);\"},\"7\":{\"isi\":\"Peraturan Menteri Dalam Negeri Nomor 15 Tahun 2023 tentang Pedoman Penyusunan Anggaran Pendapatan dan Belanja Daerah Tahun Anggaran 2024;\"},\"8\":{\"isi\":\"Peraturan Menteri Dalam Negeri Nomor 77 Tahun 2020 tentang Pedoman Teknis Pengelolaan Keuangan Daerah;\"},\"9\":{\"isi\":\"Peraturan Daerah Kabupaten Pasangkayu Nomor 5 Tahun 2023 tanggal 29 Desember 2023 tentang Anggaran pendapatan dan Belanja Daerah Tahun Anggaran 2024;\"},\"10\":{\"isi\":\"Peraturan Bupati Kabupaten Pasangkayu Nomor 27 Tahun 2023 tanggal 29 Desember 2023 tentang Penjabaran Anggaran Pendapatan dan Belanja Daerah Kebupaten Pasangkayu Tahun Anggaran 2024;\"}}', '{\"0\":{\"isi\":\"Tugas Pejabat sebagaimana dimaksud pada diktum Kesatu adalah :\",\"p_l\":\"P\"},\"1\":{\"isi\":\"Melaksanakan Pengamanan secara menyeluruh di lokasi kerja, baik perkantoran dan lingkungan untuk memastikan kondisi keamanan kantor;\",\"p_l\":\"L\"},\"2\":{\"isi\":\"Melakukan pemeriksaan pada tamu / pemilik yang akan masuk ke area kantor/kerja terutama malam hari ;\",\"p_l\":\"L\"},\"3\":{\"isi\":\"Menyalakan dan Mematikan lampu Setelah Jaga malam;\",\"p_l\":\"L\"},\"4\":{\"isi\":\"Mengecek Kunci-kunci pintu, jendela dan pagar kantor\",\"p_l\":\"L\"},\"5\":{\"isi\":\"Membuat Laporan penting kejadian-kejadian penting selama masa penjagaan pada buku laporan\",\"p_l\":\"L\"}}', '{\"0\":{\"isi\":\"Segala biaya yang timbul akibat keputusan ini dibebankan kepada Pos Anggaran Dinas Pekerjaan Umum dan Penataan Ruang Kabupaten Pasangkayu Tahun Anggaran 2024.\",\"p_l\":\"P\"}}', '{\"0\":{\"isi\":\"Keputusan ini mulai berlaku pada tanggal ditetapkan dan apabila terdapat kekeliruan didalamnya akan diperbaharui sebagaimana mestinya.\",\"p_l\":\"P\"}}', '{}', '{\"0\":{\"tembusan\":\"Bupati                                            Pasangkayu, di Pasangkayu\"},\"1\":{\"tembusan\":\"Sekretaris Daerah Kabupaten Pasangkayu di Pasangkayu\"},\"2\":{\"tembusan\":\"Inspektur Inspektorat Kabupaten Pasangkayu di Pasangkayu\"},\"3\":{\"tembusan\":\"Kepala Badan PKAD Kabupaten Pasangkayu di Pasangkayu\"},\"4\":{\"tembusan\":\"Masing-masing yang bersangkutan\"},\"5\":{\"tembusan\":\"Pertinggal\"}}', '', '', '0000-00-00 00:00:00', '', '0000-00-00 00:00:00', '', 0, 0),
