(104, '2024', '76.01', '1.03.0.00.0.00.01.0000', '22 TAHUN 2024', '2024-01-08', 'pengangkatan operator Alat Berat/Alat Besar dinas pekerjaan umum dan penataan ruang kabupaten pasangkayu tahun 2024', '198006152006041018', 'kepala', 'Pembina tingkat I, IV/b', 'Sumarlin, ST.M.AP', '{\"0\":{\"nama\":\"Hairuddin\",\"pangkat\":\"-\",\"nip\":\"Non ASN\",\"jabatan\":\"honorer\",\"jabatan_sk\":\"Operator Alat Berat\\/Besar\"},\"1\":{\"nama\":\"Sudirman\",\"pangkat\":\"-\",\"nip\":\"Non ASN\",\"jabatan\":\"honorer\",\"jabatan_sk\":\"Operator Alat Berat\\/Besar\"},\"2\":{\"nama\":\"Akbar Subianto\",\"pangkat\":\"-\",\"nip\":\"Non ASN\",\"jabatan\":\"honorer\",\"jabatan_sk\":\"Operator Alat Berat\\/Besar\"},\"3\":{\"nama\":\"Aldi\",\"pangkat\":\"-\",\"nip\":\"Non ASN\",\"jabatan\":\"honorer\",\"jabatan_sk\":\"Operator Alat Berat\\/Besar\"}}', 1, '{\"0\":{\"isi\":\"bahwa untuk kelancaran pelaksanaan sewa-menyewa\\/penggunaan alat berat daerah pada Dinas Pekerjaan Umum dan Penataan Ruang Pemerintah Daerah Kabupaten Pasangkayu, maka dipandang perlu mengangkat Operator Alat Berat\\/Besar pada Dinas Pekerjaan Umum Kabupaten Pasangkayu;\",\"p_l\":\"L\"},\"1\":{\"isi\":\"bahwa yang tersebut namanya dalam lampiran keputusan ini dipandang cakap dan mampu melaksanakan tugas;\",\"p_l\":\"L\"},\"2\":{\"isi\":\"bahwa pengangkatan sebagaimana dimaksud pada point a perlu ditetapkan dalam Keputusan Kepala Dinas.\",\"p_l\":\"L\"}}', '{\"0\":{\"isi\":\"Undang-Undang Nomor 28 Tahun 1999 tentang Penyelenggaraan Pemerintahan yang bersih dan bebas Korupsi, Kolusi dan Nepotisme (Lembaran Negara Republik Indonesia Tahun 1999 Nomor 75, Tambahan Lembaran Negara Republik Indonesia Nomor 3581);\",\"p_l\":\"L\"},\"1\":{\"isi\":\"Undang-Undang Nomor 28 tahun 2000 tentang usaha dan peran masyarakat Jasa Konstruksi (Lembaran Negara Republik Indonesia tahun 2000 Nomor 63);\",\"p_l\":\"L\"},\"2\":{\"isi\":\"Undang-Undang Nomor 7 Tahun 2003 tentang Pembentukan Kabupaten Luwu Timur dan Kabupaten Mamuju Utara di Provinsi Sulawesi Selatan (Lembaran Negara Tahun 2003 Nomor 27, Tambahan Lembaran NegaraNomor 4270);\",\"p_l\":\"L\"},\"3\":{\"isi\":\"Undang-Undang Nomor 17 Tahun 2003 tentang Keuangan Negara (Lembaran Negara Republik Indonesia Tahun 2003 Nomor 47, Tambahan Lembaran Negara Republik Indonesia Nomor 4286);\",\"p_l\":\"L\"},\"4\":{\"isi\":\"Undang-Undang Nomor 1 Tahun 2022 tentang Hubungan Keuangan Antara Pemerintah Pusat dan Pemerintah Daerah;\",\"p_l\":\"L\"},\"5\":{\"isi\":\"Undang-Undang Nomor 33 Tahun 2004 tentang Perimbangan Keuangan Antara Pemerintah Pusat dan Pemerintah Daerah (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 126, Tambahan Lembaran Negara Republik Indonesia Nomor 4438);\",\"p_l\":\"L\"},\"6\":{\"isi\":\"Undang-Undang Nomor 2 Tahun 2017 tentang Jasa Konstruksi;\",\"p_l\":\"L\"},\"7\":{\"isi\":\"Peraturan Presiden Republik Indonesia Nomor 16 Tahun 2019 tentang Pengadaan Barang\\/Jasa Pemerintah;\",\"p_l\":\"L\"},\"8\":{\"isi\":\"Peraturan Pemerintah Nomor 61 Tahun 2017 tentang Perubahan Nama Kabupaten Mamuju Utara menjadi Kabupaten Pasangkayu di Provinsi Sulawesi Barat (Lembaran Negara Republik Indonesia Tahun 2017 Nomor 312, Tambahan Lembaran Negara Republik Indonesia Nomor 6715);\",\"p_l\":\"L\"},\"9\":{\"isi\":\"Peraturan Menteri Dalam Negeri Nomor 13 Tahun 2006 tentang Pedoman Pengelolaan Keuangan Daerah sebagaimana telah diubah dengan Peraturan Menteri Dalam Negeri Nomor 59 Tahun 2007 tentang Perubahan Atas Peraturan Menteri Dalam Negeri Nomor 13 Tahun 2006 tentang Pedoman Pengelolaan Keuangan Daerah;\",\"p_l\":\"L\"},\"10\":{\"isi\":\"Peraturan Menteri Dalam Negeri Nomor 15 Tahun 2023 tentang Pedoman Penyusunan Anggaran Pendapatan dan Belanja Daerah Tahun Anggaran 2024;\",\"p_l\":\"L\"},\"11\":{\"isi\":\"Peraturan Menteri Dalam Negeri Nomor 77 Tahun 2020 tentang Pedoman Teknis Pengelolaan Keuangan Daerah;\",\"p_l\":\"L\"},\"12\":{\"isi\":\"Peraturan Daerah Kabupaten Pasangkayu Nomor 5 Tahun 2023 tanggal 29 Desember 2023 tentang Anggaran pendapatan dan Belanja Daerah Tahun Anggaran 2024;\",\"p_l\":\"L\"},\"13\":{\"isi\":\"Peraturan Bupati Kabupaten Pasangkayu Nomor 27 Tahun 2023 tanggal 29 Desember 2023 tentang Penjabaran Anggaran Pendapatan dan Belanja Daerah Kebupaten Pasangkayu Tahun Anggaran 2024;\",\"p_l\":\"L\"}}', '{\"0\":{\"isi\":\"Tugas Personil sebagaimana dimaksud pada diktum Penetapan adalah sebagai berikut :\",\"p_l\":\"P\"},\"1\":{\"isi\":\"Sebelum mengoperasikan alat, seorang operator alat wajib melakukan pemeriksaan standar rutin seperti, pemeriksaan bahan bakar dan oli;\",\"p_l\":\"L\"},\"2\":{\"isi\":\"Mengoperasikan alat berat untuk aktivitas peralatan sesuai spesifikasi pabrik asal alat berat, Melakukan manuver alat berat bermotor untuk memastikan pemindahan dan penempatan material secara akurat;\",\"p_l\":\"L\"},\"3\":{\"isi\":\"Melaporkan jika terjadi kerusakan alat berat;\",\"p_l\":\"L\"},\"4\":{\"isi\":\"Bertanggung jawab dalam hal pengangkutan dan pengiriman, serta memastikan memarkir alat berat di area yang aman;\",\"p_l\":\"L\"},\"5\":{\"isi\":\"Menjaga kesehatan alat berat, dengan cara merawat dan memperbaiki ketika ada kerusakan. Dalam hal perawatan, operator wajib melakukannya sesuai standar pabrik sehingga hasilnya optimal. Sedangkan dalam hal perbaikan, lalu wajib bekerja sama dengan mekanik dan pabrik asal alat berat jadi tidak salah dalam penanganan;\",\"p_l\":\"L\"},\"6\":{\"isi\":\"Memastikan mesin alat berat dalam keadaan mati saat tidak digunakan, dengan memeriksa kunci masih terpasang atau tidak;\",\"p_l\":\"L\"},\"7\":{\"isi\":\"Memberikan saran untuk menyempurnakan alur kerja dan meningkatkan efisiensi;\",\"p_l\":\"L\"},\"8\":{\"isi\":\"Mematuhi kode keselamatan yang ditetapkan setiap saat;\",\"p_l\":\"L\"},\"9\":{\"isi\":\"Melaksanakan tugas kedinasan lain yang diperintahkan pimpinan baik tertulis maupun lisan.\",\"p_l\":\"L\"}}', '{\"0\":{\"isi\":\"Segala biaya yang timbul akibat keputusan ini dibebankan kepada Pos Anggaran Dinas Pekerjaan Umum dan Penataan Ruang Kabupaten Pasangkayu Tahun Anggaran 2024.\",\"p_l\":\"P\"}}', '{\"0\":{\"isi\":\"Keputusan ini mulai berlaku pada tanggal ditetapkan dan apabila terdapat kekeliruan didalamnya akan diperbaharui sebagaimana mestinya.\",\"p_l\":\"P\"}}', '{}', '{\"0\":{\"isi\":\"Bupati Pasangkayu, di Pasangkayu\",\"p_l\":\"L\"},\"1\":{\"isi\":\"Sekretaris Daerah Kabupaten Pasangkayu di Pasangkayu\",\"p_l\":\"L\"},\"2\":{\"isi\":\"Inspektur Inspektorat Kabupaten Pasangkayu di Pasangkayu\",\"p_l\":\"L\"},\"3\":{\"isi\":\"Kepala Badan PKAD Kabupaten Pasangkayu di Pasangkayu\",\"p_l\":\"L\"},\"4\":{\"isi\":\"Masing-masing yang bersangkutan\",\"p_l\":\"L\"},\"5\":{\"isi\":\"Pertinggal\",\"p_l\":\"L\"}}', '', '', '0000-00-00 00:00:00', '', '2024-03-31 18:22:21', 'nabiila', 0, 0),
